sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// 1. Initialize a new record on the core User (sys_user) table
    var newUser = new GlideRecord('sys_user');
    newUser.initialize();

    // 2. Map the names and email
    newUser.first_name = current.first_name;
    newUser.last_name = current.last_name;
    newUser.email = current.email;

    // 3. Format the User ID as last_name.first_name in lowercase
    var rawUserId = current.last_name + "." + current.first_name;
    newUser.user_name = rawUserId.toLowerCase().replace(/\s+/g, ''); // Removes spaces and forces lowercase

    // 4. Insert the record into the database
    var userSysId = newUser.insert();

    // 5. Optional: Link the student record to the newly created user record
    // If you have a reference field named 'Registrar' or 'User Link' on the student table:
    // current.u_registrar = userSysId;
    // current.update(); 


})(current, previous);
